-- Reviewed question banks. Additive, immutable; activate only with matching application code.
do $$ declare v uuid; qid uuid; oid uuid; begin
      if not exists(select 1 from meqyro.quizzes where slug='brainrank') then raise exception 'Missing assessment brainrank'; end if;
      if exists(select 1 from meqyro.quiz_versions v join meqyro.quizzes q on q.id=v.quiz_id where q.slug='brainrank' and v.version='1.3') then return; end if;
      select id,'1.3','1.3','DRAFT'::meqyro.content_status from meqyro.quizzes where slug='brainrank' returning id into strict v;
end $$;
